#!/usr/bin/env bash
# Blaze Camp: is the plan builder API alive? Usage: bash check.sh   (generated by agent/packs.mjs)
set -u
BASE="https://blaze-camp-model.vercel.app"
for u in "$BASE/api/openapi" "$BASE/api/questions?lang=en" "$BASE/api/questions?lang=es" "https://github.com/Blazecamp/blaze-camp-model/blob/main/DISCLAIMER.md"; do
  printf '%-70s ' "$u"
  curl -sS -L --max-time 25 -o /dev/null -w 'HTTP %{http_code}\n' "$u" || echo 'NO ANSWER'
done
